text:
5.1 関東1都6県へ絞る
第6章のc_pref_gdp.xlsxをコード表として使います。名称だけで結合する前に、2桁の都道府県コードを保持します。

kanto_codes &lt;- c("08", "09", "10", "11", "12", "13", "14")

pref_code_map &lt;- read_excel(
  pref_data_path,
  sheet = "gdp"
) |&gt;
  transmute(
    code = pad_pref_code(code),
    pref = as.character(pref)
  ) |&gt;
  filter(code %in% kanto_codes) |&gt;
  distinct()

if (n03_ready) {
  n03_kanto &lt;- n03_clean |&gt;
    filter(pref %in% pref_code_map$pref)

  n03_kanto |&gt;
    st_drop_geometry() |&gt;
    count(pref, sort = TRUE)
}

5.2 投影座標系へ変換する
関東を扱う本章では、JGD2011の平面直角座標系第9系であるEPSG:6677を使います。座標単位はメートルです。

if (n03_ready) {
  n03_kanto_projected &lt;- n03_kanto |&gt;
    st_transform(6677)

  st_crs(n03_kanto_projected)
}







WarningEPSG:6677が常に最適とは限らない



対象地域が全国、北海道、沖縄、海外へ変われば適切な投影法も変わります。「距離を計算するから6677」と暗記するのではなく、分析範囲と目的を確認してください。

5.3 dissolve：市区町村を都県へ溶かす
sfオブジェクトをgroup_by(pref)してsummarise()すると、同じ都県に属する複数ポリゴンが一つの形状へ統合されます。この処理をdissolveと呼びます。

if (n03_ready) {
  kanto_pref_full_projected &lt;- n03_kanto_projected |&gt;
    group_by(pref) |&gt;
    summarise(.groups = "drop") |&gt;
    left_join(
      pref_code_map,
      by = join_by(pref),
      relationship = "one-to-one"
    ) |&gt;
    select(code, pref, geometry) |&gt;
    mutate(
      area_km2 = as.numeric(
        set_units(st_area(geometry), km^2)
      )
    )

  kanto_pref_full_projected |&gt;
    st_drop_geometry() |&gt;
    arrange(desc(area_km2))
}

ここでrelationship = "one-to-one"を指定することで、名称対応表の重複などによる意図しない行増殖を検出できます。

5.4 表示範囲と分析範囲を分ける
東京都の行政区域には伊豆諸島・小笠原諸島が含まれます。全域を自動ズームすると、関東本土が小さく表示されます。
本教材では、面積は全行政区域から計算し、ダッシュボード表示用のgeometryだけを関東本土へ切り出します。

if (n03_ready) {
  mainland_window &lt;- st_bbox(
    c(xmin = 138.2, ymin = 34.9, xmax = 141.1, ymax = 37.3),
    crs = st_crs(4326)
  ) |&gt;
    st_as_sfc() |&gt;
    st_transform(6677)

  kanto_pref_projected &lt;- suppressWarnings(
    st_intersection(kanto_pref_full_projected, mainland_window)
  )
}







Noteクロップは「存在しないこと」にする操作ではない



離島を分析対象から除外したのではなく、Web画面の視認性のために表示geometryを別に作っています。面積などの統計は全域geometryから計算した値を保持します。地理データでは、表示上の都合と分析上の定義を分けて記録する必要があります。

5.5 Web表示用に簡略化する
境界の頂点が多いほど、ブラウザへ送るデータが重くなります。投影座標系上で250メートルの許容誤差を与え、境界を簡略化します。

if (n03_ready) {
  size_before &lt;- object.size(kanto_pref_projected)

  kanto_pref &lt;- kanto_pref_projected |&gt;
    mutate(
      geometry = st_simplify(
        geometry,
        preserveTopology = TRUE,
        dTolerance = 250
      )
    ) |&gt;
    st_transform(4326)

  tibble(
    version = c("before", "after"),
    object_size_mb = c(
      as.numeric(size_before) / 1024^2,
      as.numeric(object.size(kanto_pref)) / 1024^2
    )
  )
}


if (n03_ready) {
  ggplot(kanto_pref) +
    geom_sf(aes(fill = area_km2), color = "white", linewidth = 0.4) +
    geom_sf_text(aes(label = pref), size = 3.5) +
    scale_fill_viridis_c(labels = label_number(big.mark = ",")) +
    labs(
      fill = "面積 (km2)",
      caption = paste(
        "資料：国土交通省『国土数値情報（行政区域）』。",
        "表示geometryは関東本土へ切り出し、簡略化。面積は全行政区域。"
      )
    ) +
    theme_void()
}

6.2 属性結合でgeometryへ載せる
2021年を選び、都県コードと名称で結合します。

if (n03_ready) {
  kanto_panel &lt;- pref_panel |&gt;
    semi_join(
      st_drop_geometry(kanto_pref),
      by = join_by(code, pref)
    )

  pref_map_2021 &lt;- kanto_pref |&gt;
    left_join(
      kanto_panel |&gt;
        filter(year == 2021),
      by = join_by(code, pref),
      relationship = "one-to-one"
    )

  pref_map_2021 |&gt;
    st_drop_geometry() |&gt;
    select(code, pref, year, gdp, compensation, compensation_to_gdp)
}


if (n03_ready) {
  ggplot(pref_map_2021) +
    geom_sf(aes(fill = gdp), color = "white", linewidth = 0.5) +
    geom_sf_text(aes(label = pref), size = 3.5) +
    scale_fill_viridis_c(
      labels = label_number(scale = 1 / 1e6, suffix = "兆円", accuracy = 1)
    ) +
    labs(
      title = "関東1都6県の県内総生産",
      subtitle = "2021年",
      fill = "GDP",
      caption = paste(
        "資料：内閣府『県民経済計算』、",
        "国土交通省『国土数値情報（行政区域）』"
      )
    ) +
    theme_void()
}







Important地図の色は「大小」を見せるが、原因を説明しない



東京のGDPが大きいことと、鉄道駅が多いことを同じ画面に載せても、それだけで鉄道がGDPを生んだとは言えません。人口、産業構成、企業本社、昼間人口、面積などが同時に影響します。第8章のダッシュボードは、探索と記述の道具として設計します。

7.2 駅グループ単位へ集約する
同じ駅が複数路線・事業者のlineとして複数行に現れることがあります。本教材ではstation_group単位へ集約し、2024年乗降客数はグループ内の最大値を採用します。
この選択は唯一の正解ではありません。合計すると事業者間の重複計上が起きる可能性があるため、最大値を使うという分析上のルールを明示しています。

if (s12_ready) {
  station_points_projected &lt;- station_lines |&gt;
    filter(
      !is.na(station_group),
      !is.na(passengers_2024),
      passengers_2024 &gt;= 0
    ) |&gt;
    st_make_valid() |&gt;
    st_transform(6677) |&gt;
    group_by(station_group, station_name) |&gt;
    summarise(
      passengers_2024 = max(passengers_2024, na.rm = TRUE),
      operator = paste(
        sort(unique(na.omit(operator))),
        collapse = " / "
      ),
      line_name = paste(
        sort(unique(na.omit(line_name))),
        collapse = " / "
      ),
      .groups = "drop"
    ) |&gt;
    st_centroid()

  station_points_projected |&gt;
    st_drop_geometry() |&gt;
    arrange(desc(passengers_2024)) |&gt;
    slice_head(n = 10)
}







Noteなぜ代表点が必要か



第8章では円マーカーで駅を描きます。そのため、駅lineの中心を代表点として作ります。厳密な駅舎座標ではなく、表示・空間結合用の代表点です。用途が「最寄駅までの距離」であれば、より精密な点データを使うべきです。

8.1 st_within()で所属都県を付ける

if (n03_ready && s12_ready) {
  station_points &lt;- station_points_projected |&gt;
    st_join(
      kanto_pref_projected |&gt;
        select(pref_code = code, pref),
      join = st_within,
      left = FALSE
    ) |&gt;
    arrange(desc(passengers_2024)) |&gt;
    distinct(station_group, .keep_all = TRUE) |&gt;
    st_transform(4326)

  station_points |&gt;
    st_drop_geometry() |&gt;
    summarise(
      stations = n(),
      prefectures = n_distinct(pref_code),
      missing_pref = sum(is.na(pref_code))
    )
}

left = FALSEとしたため、関東本土の都県ポリゴン内へ入らない駅は残りません。除外数を確認せず使うと、意図せず全国データの大部分が消えたことを見落とします。

if (n03_ready && s12_ready) {
  tibble(
    valid_station_groups = nrow(station_points_projected),
    joined_kanto_stations = nrow(station_points),
    excluded_outside_scope = nrow(station_points_projected) - nrow(station_points)
  )
}

8.2 都県別に集計する

if (n03_ready && s12_ready) {
  station_summary &lt;- station_points |&gt;
    st_drop_geometry() |&gt;
    summarise(
      stations = n(),
      passengers_sum = sum(passengers_2024, na.rm = TRUE),
      passengers_median = median(passengers_2024, na.rm = TRUE),
      largest_station = station_name[which.max(passengers_2024)],
      .by = c(pref_code, pref)
    ) |&gt;
    left_join(
      kanto_pref |&gt;
        st_drop_geometry() |&gt;
        select(pref_code = code, area_km2),
      by = join_by(pref_code),
      relationship = "one-to-one"
    ) |&gt;
    mutate(
      stations_per_1000_km2 = stations / area_km2 * 1000
    ) |&gt;
    arrange(desc(stations))

  station_summary
}

passengers_sumは、駅ごとの定義や重複の問題があるため、都県間の厳密な総輸送量ではありません。ダッシュボードでは主に駅マーカーの大きさ・フィルターに使います。

9.2 Leafletで確認する

if (n03_ready && s12_ready) {
  map_palette &lt;- colorNumeric(
    palette = "Blues",
    domain = pref_map_2021$gdp
  )

  station_display &lt;- station_points |&gt;
    filter(passengers_2024 &gt;= 50000) |&gt;
    mutate(
      label_text = paste0(
        station_name,
        "&lt;br&gt;",
        format(passengers_2024, big.mark = ","),
        " 人 / 日"
      )
    )

  leaflet(pref_map_2021) |&gt;
    addProviderTiles(providers$CartoDB.Positron) |&gt;
    addPolygons(
      fillColor = ~ map_palette(gdp),
      fillOpacity = 0.75,
      color = "white",
      weight = 1,
      label = ~ paste0(pref, ": ", format(gdp, big.mark = ","))
    ) |&gt;
    addCircleMarkers(
      data = station_display,
      radius = ~ pmax(3, pmin(12, sqrt(passengers_2024) / 45)),
      color = "#8c2d04",
      fillColor = "#fe9929",
      fillOpacity = 0.75,
      label = ~ lapply(label_text, htmltools::HTML)
    )
}

この地図を第8章では、入力に応じて再計算・更新するShinyアプリへ変えます。

