7.4 駅のフィルター

filtered_stations &lt;- reactive({
  station_points |&gt;
    filter(passengers_2024 &gt;= input$min_passengers) |&gt;
    mutate(
      marker_radius = pmax(
        3,
        pmin(13, sqrt(passengers_2024) / 45)
      )
    )
})

乗降客数をそのまま半径にすると、最大駅が画面を覆います。平方根変換と上下限を使い、面積感覚と視認性を調整します。

8.1 地図本体は一度だけ作る

output$map &lt;- renderLeaflet({
  bbox &lt;- st_bbox(pref_geometry)

  leaflet(options = leafletOptions(preferCanvas = TRUE)) |&gt;
    addProviderTiles(providers$CartoDB.Positron) |&gt;
    fitBounds(
      lng1 = bbox[["xmin"]],
      lat1 = bbox[["ymin"]],
      lng2 = bbox[["xmax"]],
      lat2 = bbox[["ymax"]]
    )
})

8.2 leafletProxy()でレイヤーだけ更新する

observe({
  current_map &lt;- map_data()
  spec &lt;- selected_spec()

  palette_domain &lt;- if (isTRUE(input$fixed_scale)) {
    pref_panel[[input$metric]]
  } else {
    current_map$map_value
  }

  palette &lt;- colorNumeric(
    palette = spec$palette,
    domain = palette_domain,
    na.color = "#d9d9d9"
  )

  leafletProxy("map", data = current_map) |&gt;
    clearGroup("prefectures") |&gt;
    clearControls() |&gt;
    addPolygons(
      group = "prefectures",
      layerId = ~ code,
      fillColor = ~ palette(map_value),
      fillOpacity = 0.78,
      color = "#ffffff",
      weight = ~ border_weight,
      label = ~ pref,
      highlightOptions = highlightOptions(
        weight = 4,
        color = "#222222",
        bringToFront = TRUE
      )
    ) |&gt;
    addLegend(
      position = "bottomright",
      pal = palette,
      values = ~ map_value,
      title = paste0(spec$short_label, " (", input$year, ")")
    )
})

renderLeaflet()で地図全体を毎回作り直すと、ズームや表示状態もリセットされます。leafletProxy()は既存の地図へ差分を送るため、操作感が安定します。
色尺度を年ごとに作り直すと、同じ色が別の年では別の値を表します。完成例では「年をまたいで色尺度を固定する」を初期値TRUEとし、時系列比較時の読み違いを防ぎます。年内の差を強調したい場合だけOFFにします。

8.3 駅レイヤーを独立して更新する

observe({
  proxy &lt;- leafletProxy("map") |&gt;
    clearGroup("stations")

  if (isTRUE(input$show_stations)) {
    proxy |&gt;
      addCircleMarkers(
        data = filtered_stations(),
        group = "stations",
        radius = ~ marker_radius,
        color = "#8c2d04",
        fillColor = "#fe9929",
        fillOpacity = 0.75,
        label = ~ station_name
      )
  }
})

都県ポリゴンの更新と駅の更新を分けると、依存する入力も分かれます。

